param([switch]$CheckOnly,[string]$Namespace='resilient-microservices-adaptive-recovery',[string]$OrderBase='http://127.0.0.1:18083',[string]$EngineBase='http://127.0.0.1:8090')
$ErrorActionPreference='Stop';$root=Resolve-Path (Join-Path $PSScriptRoot '..');$reports=Join-Path $root 'reports';New-Item -ItemType Directory -Force $reports|Out-Null;$kubectl=if($env:KUBECTL_BIN){$env:KUBECTL_BIN}else{'kubectl'}
$runId='E4-'+(Get-Date).ToString('yyyyMMdd-HHmmsszzz').Replace(':','');$reportPath=Join-Path $reports("e4-order-http500-$runId.json");$progressPath=Join-Path $reports 'e4-progress.json'
$e4TimestampDefinitions=[ordered]@{
 T0='Delay enabled: the Order delay endpoint response confirms enabled=true and delayMs=1000.'
 T1='First during-fault safe Order probe completes while the bounded delay is enabled.'
 T2='Engine action issued: timestamp on the actual execute=true E4 mitigation response; previews do not count.'
 T3='Delay-off confirmed: the Order delay endpoint response confirms enabled=false and delayMs=0.'
 T4='Recovery verified: the second distinct post-mitigation safe probe meets the existing HTTP 409, unchanged-order-count, and below-500-ms recovery predicate.'
 T5='Stable state restored: cleanup independently confirms delay off and Order Ready.'
}
$e4StableDurationDefinition='Time to stable state = T5 - T0, where T0 is confirmed delay enable and T5 is confirmed delay off plus Order Ready.'
$report=[ordered]@{runId=$runId;experiment='E4';fault=[ordered]@{type='application-delay-reuse';route='/api/internal/e3-delay';delayMs=1000;enabled=$false};timestamps=[ordered]@{T0=$null;T1=$null;T2=$null;T3=$null;T4=$null;T5=$null};timestampDefinitions=$e4TimestampDefinitions;timestampEvidence=[ordered]@{T0=$null;T1=$null;T2=$null;T3=$null;T4=$null;T5=$null};durationDefinitions=[ordered]@{timeToStableState=$e4StableDurationDefinition};preflight=[ordered]@{status='Pending';passed=$false;reason=$null;commands=@()};forward=[ordered]@{reachableBefore=$null;reachableAfter=$null;startedByRunner=$false;pid=$null;handoff='';error=$null};baseline=[ordered]@{pod=$null;podUid=$null;ready=$null;latencyMs=$null;orderCount=$null};measurements=@();engineEvaluations=@();action=$null;recovery=[ordered]@{criteria='Recovery requires a replacement Ready Order pod, delay off, unchanged order count, and two fresh consecutive HTTP 409 probes below the 500 ms Engine threshold.';podReadyAfter=$null;delayOff=$null;safeProbe=$null;latencyRecovered=$null;postProbes=@();verified=$false};cleanup=[ordered]@{faultOff=$null;ready=$null;restoration='Not applicable — no Deployment resources changed';error=$null};result=$null}
$report['telemetry']=[ordered]@{baselineZeroScraped=$null;verifiedOneScraped=$null;baselineScrapeAt=$null;verifiedScrapeAt=$null;error=$null}
Import-Module (Join-Path $PSScriptRoot 'e4-metrics.psm1') -Force
$e4ZeroScrapePending=$true
$e4OneScrapePending=$true
function Save-Report{param([string]$Path=$progressPath)$report|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $Path -Encoding utf8}
function Record-E4Timestamp([string]$Event,[string]$Timestamp,[string]$Evidence){if(-not $Timestamp -or -not $report.timestamps.Contains($Event) -or $report.timestamps[$Event]){return};try{$parsed=[DateTimeOffset]::Parse($Timestamp)}catch{return};$report.timestamps[$Event]=$parsed.ToString('o');$report.timestampEvidence[$Event]=$Evidence;Save-Report;Save-Report -Path $reportPath}
function Get-Json($url){Invoke-RestMethod -Uri $url -Method Get -TimeoutSec 5}
function Set-Delay([bool]$enabled){$body=@{enabled=$enabled;delayMs=if($enabled){1000}else{0}}|ConvertTo-Json;$r=Invoke-RestMethod -Uri ($OrderBase+'/api/internal/e3-delay') -Method Post -ContentType 'application/json' -Body $body -TimeoutSec 5;if(($r.enabled -ne $enabled) -or ([int]$r.delayMs -ne $(if($enabled){1000}else{0}))){throw "Order delay endpoint did not confirm enabled=$enabled with the expected delayMs."};return $r}
function Disable-DelayVerified{$last=$null;for($i=0;$i -lt 3;$i++){try{$r=Set-Delay $false;if($r.enabled -eq $false -and [int]$r.delayMs -eq 0){Record-E4Timestamp 'T3' (Get-Date).ToString('o') 'Order delay endpoint response confirmed enabled=false and delayMs=0.';return $true}}catch{$last=$_.Exception.Message};Start-Sleep -Milliseconds 500};if($last){$report.cleanup.error=$last};return $false}
function Get-PodSnapshot{try{$j=& $kubectl get pod -n $Namespace -l app.kubernetes.io/name=adaptive-order-service -o json|ConvertFrom-Json;$p=$j.items|Select-Object -First 1;[ordered]@{name=$p.metadata.name;uid=$p.metadata.uid;ready=($p.status.containerStatuses[0].ready -eq $true)}}catch{[ordered]@{name=$null;uid=$null;ready=$false}}}
function Wait-NewReadyPod([string]$baselineUid){for($i=0;$i -lt 60;$i++){try{$j=& $kubectl get pod -n $Namespace -l app.kubernetes.io/name=adaptive-order-service -o json|ConvertFrom-Json;foreach($p in $j.items){$ready=($p.status.containerStatuses[0].ready -eq $true);if($ready -and $p.metadata.uid -and $p.metadata.uid -ne $baselineUid){return [ordered]@{name=$p.metadata.name;uid=$p.metadata.uid;ready=$true}}}}catch{};Start-Sleep -Seconds 2};return [ordered]@{name=$null;uid=$null;ready=$false}}
function Ensure-OrderForward{$health=$null;try{$health=Get-Json ($OrderBase+'/actuator/health');if($health.status -eq 'UP'){$report.forward.reachableAfter=$true;return $true}}catch{};$existing=Get-CimInstance Win32_Process | Where-Object {$_.CommandLine -and $_.CommandLine -match 'kubectl(\.exe)?' -and $_.CommandLine -like '*port-forward svc/adaptive-order-service 18083:8083*'} | Select-Object -First 1;if($existing){$report.forward.pid=$existing.ProcessId;$report.forward.handoff='Existing verified Order forward reused';for($i=0;$i -lt 10;$i++){try{$health=Get-Json ($OrderBase+'/actuator/health');if($health.status -eq 'UP'){$report.forward.reachableAfter=$true;return $true}}catch{};Start-Sleep -Milliseconds 500};$report.forward.error='Existing Order forward did not become healthy';$report.forward.reachableAfter=$false;return $false};$log=Join-Path $reports 'e4-order-portforward.log';$errlog=Join-Path $reports 'e4-order-portforward.err.log';$pf=Start-Process $kubectl -ArgumentList '-n',$Namespace,'port-forward','svc/adaptive-order-service','18083:8083' -RedirectStandardOutput $log -RedirectStandardError $errlog -PassThru -WindowStyle Hidden;$report.forward.startedByRunner=$true;$report.forward.pid=$pf.Id;$report.forward.handoff='Runner-started forward handed off to start/stop scripts';$pf.Id | Add-Content (Join-Path $root 'gui\.portforward-pids');for($i=0;$i -lt 20;$i++){Start-Sleep -Milliseconds 500;try{$health=Get-Json ($OrderBase+'/actuator/health');if($health.status -eq 'UP'){$report.forward.reachableAfter=$true;return $true}}catch{};if($pf.HasExited){break}};$report.forward.error='Order port-forward could not be re-established';$report.forward.reachableAfter=$false;return $false}
function Invoke-Preflight{$commands=@("powershell -NoProfile -ExecutionPolicy Bypass -File .\scripts\start-demo-gui.ps1","POST $OrderBase/api/internal/e3-delay with body {enabled=false,delayMs=0}","kubectl rollout status deployment/adaptive-order-service -n $Namespace --timeout=180s");try{$snap=Get-PodSnapshot;if(-not $snap.ready){return [ordered]@{status='Blocked';passed=$false;reason='Order is not 1/1 Ready. Do not proceed if rollout times out.';commands=$commands}};$health=Get-Json ($OrderBase+'/actuator/health');if($health.status -ne 'UP'){return [ordered]@{status='Blocked';passed=$false;reason="Order health endpoint is not UP (status=$($health.status)). If the GUI port-forward is missing, run the project start-demo command.";commands=$commands}};$report.forward.reachableBefore=$true;$reset=Set-Delay $false;if($reset.enabled -ne $false -or [int]$reset.delayMs -ne 0){return [ordered]@{status='Blocked';passed=$false;reason='The E3 delay endpoint did not confirm enabled=false and delayMs=0. Run the POST reset command before retrying.';commands=$commands}};return [ordered]@{status='Passed';passed=$true;reason='Order is Ready/UP and the E3 delay reset was confirmed disabled.';commands=$commands}}catch{return [ordered]@{status='Blocked';passed=$false;reason="E4 preflight could not reach or verify Order: $($_.Exception.Message). Run the project start-demo command, then retry.";commands=$commands}}}
function Safe-Probe{$sw=[Diagnostics.Stopwatch]::StartNew();$before=$null;$after=$null;$status=$null;$message='';try{$before=(Get-Json ($OrderBase+'/api/orders')).Count;try{$r=Invoke-WebRequest -UseBasicParsing -Method Post -Uri ($OrderBase+'/api/orders') -ContentType 'application/json' -Body (@{productId=2;quantity=999999}|ConvertTo-Json) -TimeoutSec 8;$status=[int]$r.StatusCode;$message=$r.Content}catch{if($_.Exception.Response){$status=[int]$_.Exception.Response.StatusCode.value__;$message=$_.Exception.Message}else{$message=$_.Exception.Message}};$after=(Get-Json ($OrderBase+'/api/orders')).Count}catch{$message=$_.Exception.Message};[ordered]@{at=(Get-Date).ToString('o');latencyMs=if($before -ne $null -and $after -ne $null){[math]::Round($sw.Elapsed.TotalMilliseconds,3)}else{$null};status=$status;message=$message;orderCountBefore=$before;orderCountAfter=$after;orderPersisted=if($before -ne $null -and $after -ne $null){($after -ne $before)}else{$null};available=($before -ne $null -and $after -ne $null)}}
function Wait-E4MitigationScrape([int]$expected,[DateTimeOffset]$publishedAt){
 $query='adaptive_recovery_e4_mitigation_verified{job="adaptive-recovery-engine-e2"}'
 $base='http://127.0.0.1:19090/api/v1/query?query='
 $deadline=[DateTimeOffset]::UtcNow.AddSeconds(20)
 $lastError='No fresh matching project Prometheus scrape within 20 seconds.'
 do{
  try{
   $value=Invoke-RestMethod ($base+[uri]::EscapeDataString($query)) -TimeoutSec 3
   $time=Invoke-RestMethod ($base+[uri]::EscapeDataString('timestamp('+$query+')')) -TimeoutSec 3
   if(Test-E4ScrapeMatch -ValueResponse $value -TimestampResponse $time -ExpectedVerified $expected -PublishedAt $publishedAt){
    $scraped=[DateTimeOffset]::FromUnixTimeMilliseconds([long][math]::Round(([double]$time.data.result[0].value[1])*1000)).ToOffset([TimeSpan]::FromHours(5.5)).ToString('o')
    if($expected -eq 0){$report.telemetry.baselineZeroScraped=$true;$report.telemetry.baselineScrapeAt=$scraped}else{$report.telemetry.verifiedOneScraped=$true;$report.telemetry.verifiedScrapeAt=$scraped}
    Save-Report
    return $true
   }
  }catch{$lastError=$_.Exception.Message}
  if([DateTimeOffset]::UtcNow -lt $deadline){Start-Sleep -Seconds 2}
 }while([DateTimeOffset]::UtcNow -lt $deadline)
 if($expected -eq 0){$report.telemetry.baselineZeroScraped=$false}else{$report.telemetry.verifiedOneScraped=$false}
 $report.telemetry.error=$lastError
 Save-Report
 return $false
}
function Publish-E4($sample,$mitigationVerified=0){
 Invoke-RestMethod -Uri ($EngineBase+'/api/recovery/e4/sample') -Method Post -ContentType 'application/json' -Body (@{latencyMs=$sample.latencyMs;mitigationVerified=$mitigationVerified}|ConvertTo-Json)-TimeoutSec 5|Out-Null
 $publishedAt=[DateTimeOffset]::Now
 if($mitigationVerified -eq 0 -and $e4ZeroScrapePending){
  $script:e4ZeroScrapePending=$false
  if(-not (Wait-E4MitigationScrape 0 $publishedAt)){throw 'E4 baseline mitigation=0 was not confirmed by a fresh Prometheus scrape; delay was not enabled.'}
 }elseif($mitigationVerified -eq 1 -and $e4OneScrapePending){
  $script:e4OneScrapePending=$false
  [void](Wait-E4MitigationScrape 1 $publishedAt)
 }
}
function Hold-ForPrometheusScrape{ $seconds=if($env:E4_PROMETHEUS_HOLD_SECONDS){[int]$env:E4_PROMETHEUS_HOLD_SECONDS}else{16};if($seconds -gt 0){Start-Sleep -Seconds $seconds} }
if($CheckOnly){$report.result='CHECK_ONLY_PASS';$report.cleanup=[ordered]@{faultOff='Not applicable — no live fault was created';ready='Not applicable — no live fault was created';restoration='Not applicable — no live fault was created';error=$null};Save-Report -Path $reportPath;Write-Output 'E4_CHECK_ONLY_PASS';exit 0}
try{$report.preflight=Invoke-Preflight;Save-Report;if(-not $report.preflight.passed){$report.result='BLOCKED';return};$snap=Get-PodSnapshot;$report.baseline.pod=$snap.name;$report.baseline.podUid=$snap.uid;$report.baseline.ready=$snap.ready;$report.baseline.orderCount=(Get-Json ($OrderBase+'/api/orders')).Count;$bp=Safe-Probe;$report.baseline.latencyMs=$bp.latencyMs;Publish-E4 $bp;$report.measurements+=[ordered]@{phase='before';probe=$bp};Save-Report;Hold-ForPrometheusScrape
 $enableResponse=Set-Delay $true;$report.fault.enabled=$true;Record-E4Timestamp 'T0' (Get-Date).ToString('o') "Order delay endpoint response confirmed enabled=$($enableResponse.enabled) and delayMs=$($enableResponse.delayMs)."
 for($i=0;$i -lt 3;$i++){Start-Sleep -Milliseconds 750;$dp=Safe-Probe;if(-not $report.timestamps.T1 -and $dp.available){Record-E4Timestamp 'T1' $dp.at 'Timestamp from the first completed during-fault safe Order probe.'};Publish-E4 $dp;$report.measurements+=[ordered]@{phase='during';probe=$dp};$preview=Invoke-RestMethod -Uri ($EngineBase+'/api/recovery/e4/evaluate?execute=false') -Method Post -TimeoutSec 5;$preview | Add-Member -NotePropertyName execute -NotePropertyValue $false -Force;$report.engineEvaluations+=$preview;Save-Report;Hold-ForPrometheusScrape}
  $eval=$report.engineEvaluations[-1];if($eval.decision -eq 'SIMULATED_DELAY_MITIGATION'){$eval=Invoke-RestMethod -Uri ($EngineBase+'/api/recovery/e4/evaluate?execute=true') -Method Post -TimeoutSec 30;$eval | Add-Member -NotePropertyName execute -NotePropertyValue $true -Force;$report.engineEvaluations+=$eval;if($eval.at){Record-E4Timestamp 'T2' ([string]$eval.at) 'Timestamp supplied by the actual Engine execute=true E4 mitigation response; preview evaluations excluded.'};$engineVerified=($eval.actionVerified -eq $true);$eval | Add-Member -NotePropertyName engineActionVerified -NotePropertyValue $engineVerified -Force;$eval | Add-Member -NotePropertyName mitigationVerified -NotePropertyValue $engineVerified -Force;$report.engineEvaluations[-1]=$eval;$report.action=[ordered]@{decision=$eval.decision;actionVerified=$engineVerified;engineActionVerified=$engineVerified;mitigationVerified=$engineVerified};$afterSnap=Get-PodSnapshot;$report.recovery.podReadyAfter=$afterSnap.ready;if($engineVerified -and (Disable-DelayVerified)){$report.cleanup.faultOff=$true;$report.recovery.delayOff=$true}else{$report.recovery.delayOff=$false};Save-Report}
 if($report.action -and $report.recovery.podReadyAfter){$null=Ensure-OrderForward};if(Disable-DelayVerified){$report.cleanup.faultOff=$true;$report.recovery.delayOff=$true}else{$report.cleanup.faultOff=$false;$report.recovery.delayOff=$false};Save-Report
  $post=@();for($pi=0;$pi -lt 2;$pi++){if($pi -gt 0){Start-Sleep -Seconds 2};$pp=Safe-Probe;$post+=$pp;$report.recovery.postProbes+=$pp;if($pp.available){Publish-E4 $pp ([int]$report.action.actionVerified)}$report.measurements+=[ordered]@{phase='after';probe=$pp};Save-Report;Hold-ForPrometheusScrape};$safePosts=@($post|Where-Object {$_.available -and $_.status -eq 409 -and -not $_.orderPersisted});$goodPosts=@($safePosts|Where-Object {[double]$_.latencyMs -lt 500});$report.recovery.safeProbe=($safePosts.Count -eq 2);$report.recovery.latencyRecovered=($goodPosts.Count -eq 2 -and $post[0].at -ne $post[1].at);if($report.recovery.latencyRecovered){Record-E4Timestamp 'T4' ([string]$goodPosts[-1].at) 'Timestamp on the second distinct post-mitigation safe probe satisfying the existing recovery predicate.'};$report.recovery.verified=($report.action.actionVerified -and $report.action.mitigationVerified -and $report.recovery.podReadyAfter -and $report.recovery.delayOff -and $report.recovery.safeProbe -and $report.recovery.latencyRecovered);$report.result=if($report.recovery.verified){'PASSED'}else{'FAILED'};Save-Report;Hold-ForPrometheusScrape
}catch{$report.result='FAILED';$report.error=$_.Exception.Message}finally{if($report.fault.enabled){if(Disable-DelayVerified){$report.cleanup.faultOff=$true}else{$report.cleanup.faultOff=$false}}$report.fault.enabled=$false;$report.cleanup.ready=(Get-PodSnapshot).ready;if($report.cleanup.faultOff -eq $true -and $report.cleanup.ready -eq $true){Record-E4Timestamp 'T5' (Get-Date).ToString('o') 'Final cleanup independently confirmed delay disabled and the Order pod Ready.'};Save-Report -Path $progressPath;Save-Report -Path $reportPath}
Write-Output ($report|ConvertTo-Json -Depth 12);if($report.result -eq 'FAILED'){exit 1}
